"""Plain-language lookup entries; lesson IDs remain stable as lessons move."""

GLOSSARY = [
    ("discretization", "Discretization", "Replacing a continuous quantity or domain with a finite representation, such as temperatures at selected grid points. Solving the resulting equations accurately does not by itself establish that the representation is adequate.", "scientific-workflow"),
    ("residual", "Residual", "The mismatch left when a candidate answer is put back into the equations. A small mismatch needs a problem-specific justification before it can be interpreted as a small error in the answer.", "scientific-workflow"),
    ("iteration", "Iteration", "One repetition of an update procedure. Its cost and the number of repetitions required to meet the acceptance rule both affect completion time.", "scientific-workflow"),
    ("power", "Power", "The rate of energy use. One watt is one joule per second; power alone does not say how much energy a complete task requires.", "physical-design"),
    ("energy", "Energy", "The amount consumed over an interval, measured in joules. A device drawing 10 watts for 3 seconds uses 30 joules. For changing power, add the energy used during each part of the run. Include the same components and intervals when comparing tasks.", "physical-design"),
    ("placement", "Physical placement", "Choosing locations for circuit blocks or cells. Their positions affect wire lengths, routing space, and the delivery of power.", "physical-design"),
    ("routing", "Physical routing", "Choosing the actual wire paths connecting circuit elements. A logical connection still needs space and has electrical effects.", "physical-design"),
    ("atomicity", "Atomicity", "An all-or-nothing rule for an operation. The allowed observation or recovery state includes the whole change or none of it, rather than a partial change.", "durable-update"),
    ("durability", "Durability", "A promise that an acknowledged change survives the specified failures. The promise must name those failures and the acknowledgement point.", "durable-update"),
    ("bandwidth", "Bandwidth", "How much data a connection can transfer per unit of time. A high transfer rate does not imply a short delay for an individual access.", "s3"),
    ("barrier", "Barrier", "A point where work must wait until all required participants have reached it. The last required participant determines when the group can continue.", "s7"),
    ("batching", "Batching", "Handling several requests together so they can share work or setup costs. Waiting to assemble the group can increase an individual request's delay.", "queues-and-batching"),
    ("bottleneck", "Bottleneck", "The part that limits the result you are measuring. If every completed request needs one disk read and the disk serves at most 100 reads per second, adding processors cannot raise completion above 100 requests per second under that assumption. Reusing data could remove the disk-read requirement and change the limit.", "s1"),
    ("cache", "Cache", "Storage that keeps selected data available for reuse. Its benefit depends on whether the data is reused, still valid, and cheaper to retrieve than to obtain again.", "s3"),
    ("cache-ownership", "Cache ownership", "A rule saying which task may place, replace, or read data in a reserved cache region. Physical presence of bytes and permission to use them are separate facts.", "s3"),
    ("checkpoint", "Checkpoint", "Saved information from which a calculation can resume. A saved training step might need both model values and the optimizer's records of earlier updates. Saving only one may not reproduce the next step. In a multi-part system, the saved pieces must fit together, and their storage must survive the failure being considered.", "s7"),
    ("compiler", "Compiler", "Software that translates a program into an executable form, choosing operations and storage arrangements while preserving the behavior the program requires.", "s6"),
    ("concurrency", "Concurrency", "Several activities being in progress over the same period. They need not execute simultaneously; one may progress while another waits.", "dependencies-and-pipelines"),
    ("cut", "Cut", "A boundary dividing a network into two sets of parts. Traffic crossing the boundary must fit through the connections that cross it.", "s4"),
    ("dependency", "Dependency", "A requirement that one operation obtain a result or condition produced by another before it can proceed.", "dependencies-and-pipelines"),
    ("decode", "Decode", "The repeating part of language-model serving that uses saved prompt state to produce later output tokens. Its delay is often measured between tokens, separately from the first-token delay.", "queues-and-batching"),
    ("error-detection", "Error detection", "Recognizing that something is wrong under a stated error model. Detection alone does not identify the original value or provide a safe recovery action.", "s8"),
    ("false-positive", "False positive", "An ordinary event incorrectly flagged as a problem. If 10 of 1,000 ordinary events trigger an alert, the false-positive rate is 1%. That does not mean 1% of all alerts are wrong: that fraction also depends on how many actual problems produced alerts.", "s9"),
    ("fusion", "Fusion", "Combining operations into one execution step or pass, often to avoid storing and rereading intermediate values. Other users of those values may constrain whether this is allowed.", "s6"),
    ("constant-growth", "Constant cost (O(1))", "A cost that stays below a fixed bound as the named input or system size grows; it need not be exactly equal in every case. Keeping between one and four copies regardless of worker count is one example. One host copy per model is also constant with respect to worker count, but its size can grow with the model. Name what is growing and what is being counted. O(1) does not mean free.", "s1"),
    ("cuda-graph", "CUDA Graph", "A recorded sequence of GPU operations that can be launched again with low host-side overhead. The recorded sequence usually needs fixed launch shapes and stable buffer locations; the data stored in those buffers can still change between replays.", "s6"),
    ("geometric-mean", "Geometric mean", "A way to combine positive ratios: multiply the ratios and take the root matching the number of ratios. For example, the geometric mean of 2 and 0.5 is 1. It summarizes a set of ratios; it does not say every case had that result.", "s8"),
    ("goodput", "Goodput", "The rate of useful completed work under a stated acceptance rule, such as requests that meet both latency limits. Unlike raw throughput, it excludes completions that fail that rule. The included work and rule must be named.", "s10"),
    ("latency", "Latency", "Elapsed time between specified start and end events. A request that waits 8 milliseconds and runs for 2 has an arrival-to-completion latency of 10 milliseconds. Timing only its execution would report 2, so always name the start and end.", "s1"),
    ("prefill", "Prefill", "The first language-model serving phase: reading the input prompt and preparing the saved state needed to generate an answer. Its completion controls when the first token can appear.", "queues-and-batching"),
    ("locality", "Locality", "A pattern in which work reuses the same data or nearby data. Such patterns can make keeping data close worthwhile; proximity alone does not guarantee reuse.", "s3"),
    ("parallelism", "Parallel execution", "Work actually happening at the same time on available resources. Dependencies and shared resources limit which operations can run together.", "dependencies-and-pipelines"),
    ("kv-cache", "Key–value cache", "Stored intermediate values from earlier tokens that a language model consults while producing later tokens. It grows with the context and active requests, so both its capacity and the time needed to read it can limit serving.", "s3"),
    ("outlier", "Outlier", "A value far from most values in the group being represented. If one scale must cover both the outlier and ordinary values, the ordinary values may lose useful detail when rounded to a small set of levels.", "s2"),
    ("percentile", "Percentile", "A threshold at a chosen position after measurements are sorted. With 100 delays and the nearest-rank convention, the 99th percentile is the 99th value in ascending order. One observation can still be slower. Different calculation conventions can give different thresholds, so state the one used.", "queues-and-batching"),
    ("processing-in-memory", "Processing-in-memory", "Doing selected calculations inside or beside memory so some values do not have to travel to a separate processor first. The extra logic competes with storage capacity, and the result still depends on memory access order, arithmetic accuracy, and coordination with the rest of the system.", "s3"),
    ("pipeline", "Pipeline", "Overlapping different items at different stages of processing. Each item still follows its required stage order, and the slowest stage can limit the continuing completion rate.", "dependencies-and-pipelines"),
    ("parameter-server", "Parameter server", "A service that holds shared model values and coordinates updates from several training groups. It can simplify coordination, but its communication, stored state, and recovery become part of the system's cost.", "training-workflow"),
    ("pseudo-gradient", "Pseudo-gradient", "A model change used as an approximate update direction when a direct gradient at the shared model is unavailable. Its usefulness depends on how the local and shared model states differ; the name alone does not make it accurate.", "training-workflow"),
    ("quantization", "Quantization", "Representing values using a limited set of levels. Values between levels must be approximated, and values outside the supported range need a separate handling rule.", "s2"),
    ("quorum", "Quorum", "A group whose participation a protocol requires before taking an action. One protocol might require replies from three of five machines. Any two such groups share at least one machine: six different members cannot fit among five. That overlap is useful only with rules governing what each reply promises and what state survives failures. Other protocols require different groups; a quorum does not always mean a majority.", "s7"),
    ("queue", "Queue", "Work waiting for access to a resource. The order of service is a policy choice; a queue is not necessarily served in arrival order.", "queues-and-batching"),
    ("recovery", "Recovery", "Returning to usable, permitted operation after a failure. This may require restoring state, repeating work, and preventing repeated work from taking effect twice.", "s7"),
    ("rounding", "Rounding", "Replacing a value with a nearby representable value. Rounding intermediate results can make the order of calculation affect the final answer.", "s2"),
    ("safety-property", "Safety property", "A requirement that a forbidden event never occur, such as exceeding a queue's capacity. It does not by itself guarantee that useful work eventually finishes.", "s8"),
    ("scheduling", "Scheduling", "Choosing which work gets access to which resource and when. A policy that improves average delay may treat some requests poorly.", "queues-and-batching"),
    ("slack", "Slack", "The time left between an operation's predicted completion and the limit it must meet. Using slack for extra work is safe only if switching cost and prediction error also fit inside it.", "queues-and-batching"),
    ("service-level-objective", "Service-level objective (SLO)", "A stated limit a service promises to meet, such as a maximum first-response delay or a maximum gap between later outputs. The promise must say which requests, measurement boundary, and share of requests it covers; an average alone can hide missed promises.", "s10"),
    ("side-channel", "Side channel", "An observable effect, such as timing or shared-resource state, that reveals information beyond the intended output.", "s9"),
    ("sparsity", "Sparsity", "Having many absent or zero entries in a representation. Exploiting it requires a way to identify and process what remains without spending more than the skipped work saves.", "s5"),
    ("stale-update", "Stale update", "A change calculated from an older version of shared state than the one currently in use. It may still help, but the system must account for its age and usefulness before combining it with newer changes.", "training-workflow"),
    ("specification", "Specification", "The behavior a system promises, including its assumptions and permitted exceptions. Tests and proofs need this target to establish what counts as correct.", "s8"),
    ("threat-model", "Threat model", "A description of what an attacker can control and observe, what must be protected, and which components are trusted.", "s9"),
    ("throughput", "Throughput", "The rate at which work finishes over a stated interval. Completing 200 requests in 2 seconds gives 100 requests per second for that interval. It does not say that each request took 10 milliseconds: requests may overlap or spend different amounts of time waiting.", "s1"),
    ("ttft", "Time to first token (TTFT)", "The elapsed time from a language-model request arriving until its first output token is delivered. It does not describe the gaps between later tokens.", "queues-and-batching"),
    ("tpot", "Time per output token (TPOT)", "The average delay between later output tokens in a language-model response. A request can meet its first-token limit while violating its token-gap limit, or the reverse.", "queues-and-batching"),
    ("tiling", "Tiling", "Dividing work into blocks so that data can be reused in limited fast storage before moving to another block.", "s6"),
    ("topology", "Topology", "Which parts connect to which others. Transfer time also depends on route choice, connection capacities, and competing traffic.", "s4"),
    ("virtual-deadline", "Virtual deadline", "A time budget assigned to one stage of a larger task so the stage gets a proportional share of the task's deadline. It is an allocation rule, not automatically a hard guarantee that the stage will finish by that time.", "queues-and-batching"),
]
